<script setup>
import { onMounted, ref } from 'vue'; import Button from 'primevue/button'; import Dialog from 'primevue/dialog'; import InputText from 'primevue/inputtext'; import DatePicker from 'primevue/datepicker'; import Message from 'primevue/message'; import { useConfirm } from 'primevue/useconfirm'; import StatusTag from '../../components/StatusTag.vue'; import LoadingState from '../../components/LoadingState.vue'; import EmptyState from '../../components/EmptyState.vue'; import api,{errorMessage} from '../../services/api'; import {formatDate} from '../../utils/status'
const confirm=useConfirm(), passes=ref([]),loading=ref(true),error=ref(''),dialog=ref(false),saving=ref(false),formError=ref('');const form=ref({visitorName:'',visitorPhone:'',validFrom:null,validUntil:null});const local=(v)=>{const d=new Date(v),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}:00`};const load=async()=>{loading.value=true;try{passes.value=(await api.get('/visitor-passes/my')).data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}};const open=()=>{form.value={visitorName:'',visitorPhone:'',validFrom:null,validUntil:null};formError.value='';dialog.value=true};const save=async()=>{if(!form.value.visitorName||!form.value.validFrom||!form.value.validUntil){formError.value='Vui lòng điền đủ thông tin bắt buộc.';return}if(form.value.validFrom>=form.value.validUntil){formError.value='Thời gian kết thúc phải sau thời gian bắt đầu.';return}saving.value=true;try{await api.post('/visitor-passes',{visitorName:form.value.visitorName,visitorPhone:form.value.visitorPhone||null,validFrom:local(form.value.validFrom),validUntil:local(form.value.validUntil)});dialog.value=false;await load()}catch(e){formError.value=errorMessage(e)}finally{saving.value=false}};const cancel=(pass)=>confirm.require({message:`Hủy thẻ khách ${pass.code}?`,header:'Hủy đăng ký khách',acceptLabel:'Hủy',accept:async()=>{try{await api.patch(`/visitor-passes/${pass.id}/cancel`);await load()}catch(e){error.value=errorMessage(e)}}});onMounted(load)
</script>
<template><div class="page-heading"><div><h1>Khách thăm</h1><p>Đăng ký và theo dõi lượt khách đến căn hộ.</p></div><Button label="Đăng ký khách" icon="pi pi-user-plus" @click="open" /></div><LoadingState v-if="loading" /><div v-else-if="error" class="error-panel">{{error}}</div><EmptyState v-else-if="!passes.length" icon="pi pi-users" title="Chưa có khách đăng ký" /><div v-else class="visitor-grid"><article v-for="pass in passes" :key="pass.id" class="visitor-card"><div class="visitor-top"><strong class="code">{{pass.code}}</strong><StatusTag :value="pass.status" /></div><h3>{{pass.visitorName}}</h3><span class="muted">{{pass.visitorPhone||'Không có số điện thoại'}}</span><div class="card-meta"><span><i class="pi pi-building" /> {{pass.apartment?.buildingCode}} · {{pass.apartment?.unitNumber}}</span><span><i class="pi pi-clock" /> Từ {{formatDate(pass.validFrom)}}</span><span><i class="pi pi-clock" /> Đến {{formatDate(pass.validUntil)}}</span></div><div class="card-actions"><Button v-if="pass.status==='ACTIVE'" label="Hủy" severity="danger" text @click="cancel(pass)" /></div></article></div><Dialog v-model:visible="dialog" modal header="Đăng ký khách" :style="{width:'min(38rem,94vw)'}"><Message v-if="formError" severity="error">{{formError}}</Message><div class="form-grid"><div class="field full"><label>Họ tên khách</label><InputText v-model.trim="form.visitorName" placeholder="Nguyễn Văn Minh" /></div><div class="field full"><label>Số điện thoại</label><InputText v-model.trim="form.visitorPhone" placeholder="0912345678" /></div><div class="field"><label>Hiệu lực từ</label><DatePicker v-model="form.validFrom" show-time hour-format="24" :min-date="new Date()" /></div><div class="field"><label>Hiệu lực đến</label><DatePicker v-model="form.validUntil" show-time hour-format="24" :min-date="new Date()" /></div></div><p class="muted">Một thẻ khách có hiệu lực tối đa 24 giờ.</p><div class="dialog-footer"><Button label="Hủy" text @click="dialog=false" /><Button label="Tạo thẻ khách" :loading="saving" @click="save" /></div></Dialog></template>
